CREATE TABLE public.educational_visuals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, topic text NOT NULL, preferences jsonb NOT NULL DEFAULT '{}'::jsonb, plan jsonb, status text NOT NULL DEFAULT 'planning', storage_path text, error text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, DELETE ON public.educational_visuals TO authenticated;
GRANT ALL ON public.educational_visuals TO service_role;
ALTER TABLE public.educational_visuals ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own visuals" ON public.educational_visuals FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY "Delete own visuals" ON public.educational_visuals FOR DELETE TO authenticated USING (user_id = auth.uid());
CREATE INDEX educational_visuals_owner_time ON public.educational_visuals(user_id, created_at DESC);
CREATE TABLE public.visual_accuracy_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), visual_id uuid NOT NULL REFERENCES public.educational_visuals(id) ON DELETE CASCADE, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.visual_accuracy_reports TO authenticated;
GRANT ALL ON public.visual_accuracy_reports TO service_role;
ALTER TABLE public.visual_accuracy_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own reports" ON public.visual_accuracy_reports FOR SELECT TO authenticated USING(user_id = auth.uid());
CREATE POLICY "Report own visual" ON public.visual_accuracy_reports FOR INSERT TO authenticated WITH CHECK(user_id = auth.uid() AND length(reason) BETWEEN 10 AND 2000 AND EXISTS (SELECT 1 FROM public.educational_visuals v WHERE v.id = visual_id AND v.user_id = auth.uid()));
CREATE TABLE public.visual_usage (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.visual_usage TO service_role;
ALTER TABLE public.visual_usage ENABLE ROW LEVEL SECURITY;
CREATE INDEX visual_usage_owner_time ON public.visual_usage(user_id, created_at);
CREATE TABLE public.visual_ai_blocks (user_id uuid PRIMARY KEY, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.visual_ai_blocks TO service_role;
ALTER TABLE public.visual_ai_blocks ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.claim_visual_usage(_user_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN
PERFORM pg_advisory_xact_lock(hashtextextended(_user_id::text, 0));
IF EXISTS (SELECT 1 FROM public.visual_ai_blocks WHERE user_id = _user_id) THEN RAISE EXCEPTION 'AI access paused. Ask the site owner to restore access before starting a new request.'; END IF;
IF EXISTS (SELECT 1 FROM public.profiles WHERE id = _user_id AND suspended) THEN RAISE EXCEPTION 'Your account is suspended.'; END IF;
IF EXISTS (SELECT 1 FROM public.visual_usage WHERE user_id = _user_id AND created_at > now() - interval '20 seconds') THEN RAISE EXCEPTION 'Please wait 20 seconds between visual requests.'; END IF;
IF (SELECT count(*) FROM public.visual_usage WHERE user_id = _user_id AND created_at >= date_trunc('day', now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC') >= 20 THEN RAISE EXCEPTION 'Daily visual limit reached (20 requests). Try again tomorrow.'; END IF;
INSERT INTO public.visual_usage(user_id) VALUES (_user_id);
END; $$;
REVOKE ALL ON FUNCTION public.claim_visual_usage(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.claim_visual_usage(uuid) TO service_role;
CREATE POLICY "Read own visual files" ON storage.objects FOR SELECT TO authenticated USING(bucket_id = 'educational-visuals' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Save own visual files" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id = 'educational-visuals' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Delete own visual files" ON storage.objects FOR DELETE TO authenticated USING(bucket_id = 'educational-visuals' AND (storage.foldername(name))[1] = auth.uid()::text);